"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { ChevronUp, ChevronDown, AlertCircle, Loader2, Package, RefreshCw, Search } from 'lucide-react';
import Layout from "./Layout"; // Adjust path to your Chef-specific Layout

export default function ChefProductList() {
  const [products, setProducts] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [sortDirection, setSortDirection] = useState("asc");
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedZone, setSelectedZone] = useState("");
  const [selectedYear, setSelectedYear] = useState("");
  const [zones, setZones] = useState([]);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setIsLoading(true);
    setError("");
    const token = localStorage.getItem("token");

    try {
      const [productsRes, zonesRes] = await Promise.all([
        axios.get(`${process.env.REACT_APP_API_URL}/api/products`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${process.env.REACT_APP_API_URL}/api/zones`, { headers: { Authorization: `Bearer ${token}` } }),
      ]);
      setProducts(productsRes.data);
      setZones(zonesRes.data);
    } catch (err) {
      setError(err.response?.data?.message || "Erreur lors de la récupération des données");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSort = () => {
    setSortDirection(sortDirection === "asc" ? "desc" : "asc");
  };

  const getSortIcon = () => {
    return sortDirection === "asc" ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />;
  };

  const filteredProducts = products
    .filter((product) => product.nameProduct.toLowerCase().includes(searchTerm.toLowerCase()))
    .filter((product) => (selectedZone ? product.zoneId?._id === selectedZone : true))
    .filter((product) => (selectedYear ? new Date(product.expirationDate).getFullYear().toString() === selectedYear : true));

  const sortedProducts = [...filteredProducts].sort((a, b) => {
    const dateA = new Date(a.expirationDate);
    const dateB = new Date(b.expirationDate);
    return sortDirection === "asc" ? dateA - dateB : dateB - dateA;
  });

  const years = Array.from(new Set(products.map((p) => new Date(p.expirationDate).getFullYear()))).sort();

  return (
    <Layout>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-[#C8A45D/30]/50">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <div>
                <h1 className="text-2xl font-bold tracking-tight">Liste des Produits</h1>
                <p className="text-white/80 mt-1 text-sm">Produits disponibles triés par date d'expiration</p>
              </div>
            </div>
          </div>

          {error && (
            <div className="mx-6 my-4 p-4 bg-red-50 border-l-4 border-red-500 rounded-r-lg flex items-center gap-3">
              <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0" />
              <p className="text-red-700 text-sm">{error}</p>
            </div>
          )}

          <div className="p-4 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
            <div className="flex flex-col sm:flex-row gap-4 w-full sm:w-auto">
              <div className="relative w-full sm:w-64">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
                <input
                  type="text"
                  placeholder="Rechercher par nom..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10 pr-4 py-2 w-full border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent"
                />
              </div>
              <select
                value={selectedZone}
                onChange={(e) => setSelectedZone(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent"
              >
                <option value="">Toutes les zones</option>
                {zones.map((zone) => (
                  <option key={zone._id} value={zone._id}>
                    {zone.zoneName}
                  </option>
                ))}
              </select>
              <select
                value={selectedYear}
                onChange={(e) => setSelectedYear(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent"
              >
                <option value="">Toutes les années</option>
                {years.map((year) => (
                  <option key={year} value={year}>
                    {year}
                  </option>
                ))}
              </select>
            </div>
            <button
              onClick={fetchData}
              className="flex items-center gap-2 text-[#00717F] hover:text-[#C8A45D] transition-colors duration-200 text-sm font-medium"
            >
              <RefreshCw className="h-4 w-4" /> Rafraîchir
            </button>
          </div>

          {isLoading ? (
            <div className="flex justify-center items-center h-64">
              <div className="flex flex-col items-center gap-2">
                <Loader2 className="h-10 w-10 text-[#00717F] animate-spin" />
                <p className="text-[#00717F] text-sm font-medium">Chargement des produits...</p>
              </div>
            </div>
          ) : (
            <div className="overflow-x-auto px-4 pb-6">
              <table className="min-w-full divide-y divide-[#C8A45D/30]">
                <thead>
                  <tr className="bg-[#F5F6FA] text-[#00717F]">
                    <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider rounded-tl-lg">Nom</th>
                    <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider">Quantité</th>
                    <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider">Unité</th>
                    <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider">Zone</th>
                    <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider cursor-pointer group rounded-tr-lg" onClick={handleSort}>
                      <div className="flex items-center gap-1">
                        Date d'Expiration
                        <span className="bg-[#00717F]/10 p-1 rounded group-hover:bg-[#00717F]/20 transition-colors duration-200">
                          {getSortIcon()}
                        </span>
                      </div>
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-[#C8A45D/30]/30">
                  {sortedProducts.length === 0 ? (
                    <tr>
                      <td colSpan={5} className="py-8 text-center text-gray-500">
                        <Package className="h-12 w-12 mx-auto mb-2 text-gray-400" />
                        Aucun produit trouvé
                      </td>
                    </tr>
                  ) : (
                    sortedProducts.map((product) => (
                      <tr key={product._id} className="hover:bg-[#F5F6FA]/30 transition-colors duration-150">
                        <td className="py-4 px-4 text-sm font-medium text-gray-900">{product.nameProduct}</td>
                        <td className="py-4 px-4 text-sm text-#333333">{product.quantity}</td>
                        <td className="py-4 px-4 text-sm text-#333333">{product.unity === "unit" ? "unité" : product.unity}</td>
                        <td className="py-4 px-4 text-sm">
                          {product.zoneId?.zoneName ? (
                            <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-[#C8A45D/20] text-[#00717F]">
                              {product.zoneId.zoneName}
                            </span>
                          ) : (
                            <span className="text-gray-500">N/A</span>
                          )}
                        </td>
                        <td className="py-4 px-4 text-sm">
                          {new Date() > new Date(product.expirationDate) ? (
                            <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-800">
                              Expiré: {new Date(product.expirationDate).toLocaleDateString('fr-FR')}
                            </span>
                          ) : (
                            <span className="text-#333333">{new Date(product.expirationDate).toLocaleDateString('fr-FR')}</span>
                          )}
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </Layout>
  );
}
